# Find all rectangular regions and their colors
# Look for maximal rectangles of each color

def find_maximal_rectangles(grid):
    """Find all maximal rectangles of each color"""
    h, w = len(grid), len(grid[0])
    all_rects = []
    for color in set(val for row in grid for val in row):
        for r in range(h):
            for c in range(w):
                if grid[r][c] == color:
                    # Try to expand as much as possible
                    max_r, max_c = r, c
                    while max_r + 1 < h and all(grid[max_r+1][c] == color):
                        max_r += 1
                    while max_c + 1 < w and all(grid[r][max_c+1] == color):
                        max_c += 1
                    # Check if it's a valid rectangle
                    is_rect = True
                    for rr in range(r, min(max_r+1, h)):
                        for cc in range(c, min(max_c+1, w)):
                            if grid[rr][cc] != color:
                                is_rect = False
                                break
                        if not is_rect:
                            break
                    if is_rect:
                        all_rects.append((r, c, max_r, max_c, color))
    return all_rects

# Better approach: find connected regions and check if they're rectangular
def find_connected_rectangular_regions(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    regions = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] not in [2, 0]:  # Not background and not "0"
                color = grid[r][c]
                # BFS to find all connected cells of this color
                cells = []
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    rr, cc = stack.pop()
                    cells.append((rr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = rr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc] and grid[nr][nc] == color:
                            visited[nr][nc] = True
                            stack.append((nr, nc))

                # Check if this region forms a rectangle
                if not cells:
                    continue
                min_r, max_r = min(x[0] for x in cells), max(x[0] for x in cells)
                min_c, max_c = min(x[1] for x in cells), max(x[1] for x in cells)
                rect_area = (max_r - min_r + 1) * (max_c - min_c + 1)
                actual_area = len(cells)

                if rect_area == actual_area:
                    regions.append((min_r, min_c, max_r, max_c, color))

    return regions

